const FISH_FULL = {
BK: 'Brook Trout', RT: 'Rainbow Trout', GT: 'Golden Trout',
BN: 'Brown Trout', CT: 'Cutthroat Trout', KOK: 'Kokanee Salmon',
GTXRT: 'Golden×Rainbow Hybrid', GTxRT: 'Golden×Rainbow Hybrid'
};

const USE_FULL = { H: 'High Use', M: 'Moderate Use', L: 'Low Use' };

// Populate unit filter
const unitSelect = document.getElementById('filter-unit');
const units = [...new Set(LAKES.map(l => l.unit))].sort();
units.forEach(u => {
const opt = document.createElement('option');
opt.value = u; opt.textContent = u;
unitSelect.appendChild(opt);
});

// State
let sortCol = 'name', sortDir = 1;
let filtered = [...LAKES];

function getFishTags(fishStr) {
return fishStr.split(',').map(f => {
const code = f.trim().toUpperCase().replace('×', 'X');
const cls = code === 'GTXRT' ? 'GTXRT' : code;
return `<span class="fish-tag fish-${cls}" title="${FISH_FULL[f.trim()] || f.trim()}">${f.trim()}</span>`;
}).join('');
}

function render() {
const tbody = document.getElementById('lake-body');
const noRes = document.getElementById('no-results');
const count = document.getElementById('count');

count.textContent = `${filtered.length} of ${LAKES.length} lakes`;

if (filtered.length === 0) {
tbody.innerHTML = '';
noRes.style.display = 'block';
return;
}
noRes.style.display = 'none';

tbody.innerHTML = filtered.map(l => `
<tr>
<td class="td-name">${l.name}</td>
<td class="td-fish">${getFishTags(l.fish)}</td>
<td class="td-unit">${l.unit}</td>
<td class="td-drainage">${l.drainage}</td>
<td class="td-trailhead">${l.trailhead}</td>
<td class="td-acres">${l.acres.toFixed(3)}</td>
<td><span class="use-badge use-${l.use}" title="${USE_FULL[l.use]}">${l.use}</span></td>
</tr>
`).join('');
}

function applyFilters() {
const q = document.getElementById('search').value.toLowerCase().trim();
const unit = document.getElementById('filter-unit').value;
const fish = document.getElementById('filter-fish').value;
const use = document.getElementById('filter-use').value;

filtered = LAKES.filter(l => {
if (q && !l.name.toLowerCase().includes(q) && !l.drainage.toLowerCase().includes(q) && !l.trailhead.toLowerCase().includes(q)) return false;
if (unit && l.unit !== unit) return false;
if (fish && !l.fish.split(',').map(f => f.trim()).includes(fish)) return false;
if (use && l.use !== use) return false;
return true;
});

// Apply sort
filtered.sort((a, b) => {
let av = a[sortCol], bv = b[sortCol];
if (sortCol === 'acres') return (av - bv) * sortDir;
return String(av).localeCompare(String(bv)) * sortDir;
});

render();
}

// Sort headers
document.querySelectorAll('thead th[data-col]').forEach(th => {
th.addEventListener('click', () => {
const col = th.dataset.col;
if (!['name','unit','drainage','trailhead','acres'].includes(col)) return;
if (sortCol === col) sortDir *= -1;
else { sortCol = col; sortDir = 1; }

document.querySelectorAll('thead th').forEach(t => t.classList.remove('sorted'));
th.classList.add('sorted');
const arrow = th.querySelector('.sort-arrow');
if (arrow) arrow.textContent = sortDir === 1 ? '↑' : '↓';

applyFilters();
});
});

// Wire controls
['search','filter-unit','filter-fish','filter-use'].forEach(id => {
document.getElementById(id).addEventListener('input', applyFilters);
});

document.getElementById('btn-reset').addEventListener('click', () => {
document.getElementById('search').value = '';
document.getElementById('filter-unit').value = '';
document.getElementById('filter-fish').value = '';
document.getElementById('filter-use').value = '';
sortCol = 'name'; sortDir = 1;
document.querySelectorAll('thead th').forEach(t => {
t.classList.remove('sorted');
const a = t.querySelector('.sort-arrow');
if (a) a.textContent = '↕';
});
applyFilters();
});

// Initial render
applyFilters();
